    def __init__(self, cfg, model_path="sk_model.joblib"):
        super().__init__(cfg)
        self.model_path = model_path
        self.model = None

    @property
    def name(self):
        return "sklearn"

    def load(self):
        if os.path.exists(self.model_path):
            self.model = joblib.load(self.model_path)
        else:
            # Example: binary classifier with partial_fit support
            self.model = SGDClassifier(max_iter=5)

    def predict(self, image_path):
        # For tabular/text, image_path is not used. This function is a placeholder.
        return []

    def retrain(self, annotations):
        # annotations: list of (X, y) tuples; here we assume caller supplies feature vectors
        if self.model is None:
            self.load()
        X = np.array([a[0] for a in annotations])
        y = np.array([a[1] for a in annotations])
        # Use partial_fit if available
        if hasattr(self.model, "partial_fit"):
            classes = np.unique(y)
            self.model.partial_fit(X, y, classes=classes)
        else:
            self.model.fit(X, y)
        joblib.dump(self.model, self.model_path)

